using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF Core 9 breaking change: discriminator property renamed to "$type".
            // Preserve "Discriminator" to stay compatible with existing 500K documents.
            entity.HasDiscriminator<string>("Discriminator").HasValue("Product");

            // EF Core 9 breaking change: id format changed from "EntityName|Key" to just "Key".
            // Preserve the EF8 format so existing documents remain accessible.
            entity.HasKey(p => p.Id);
            entity.Property(p => p.Id)
                  .ToJsonProperty("id")
                  .HasValueGenerator<LegacyCosmosIdGenerator>();

            // EF Core 9 removed support for client-side index definitions (HasIndex).
            // Indexes must be managed in the Azure portal or via ARM/Bicep templates.
            // entity.HasIndex(p => p.Sku); // REMOVED — no longer supported
        });
    }
}

